using System;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using TextureFlow.UnityEditor;
public static class FlowSmoke {
 static int checks;static string report="";static Renderer shoes;static Material original,other,generated;static bool oldPlayOptions;static EnterPlayModeOptions oldOptions;
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);checks++;report+="PASS "+message+"\n";}
 static void Refuses(Action action,string message){bool failed=false;try{action();}catch(Exception){failed=true;}Check(failed,message);}
 static FlowTarget Target(){return FlowBridge.Snapshot().targets.Single(t=>t.instanceId==shoes.GetInstanceID()&&t.slot==0);}
 static FlowCommand Apply(string path){return new FlowCommand{requestId=Guid.NewGuid().ToString("N"),sessionId=FlowBridge.Session,action="apply",target=Target(),materialPath=path};}
 static void Finish(int code){File.WriteAllText("unity-smoke-result.txt",report+checks+" Unity checks passed.\n");Debug.Log(report);EditorApplication.Exit(code);}
 public static void Run(){try{
  AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var request=Directory.GetFiles("Assets/TextureFlow/Exports","flow-request.json",SearchOption.AllDirectories).OrderByDescending(File.GetLastWriteTimeUtc).First();
  report+=FlowImporter.Import(request)+"\n";string dir=Path.GetDirectoryName(request).Replace('\\','/');string materialPath=dir+"/Animated.mat";generated=AssetDatabase.LoadAssetAtPath<Material>(materialPath);
  Check(generated!=null&&generated.shader.name=="TextureFlow/Masked Scroll","generated shader and material");Check(generated.GetTexture("_Mask")!=null&&generated.GetTexture("_FlowTex")!=null,"texture references");Check(Math.Abs(generated.GetVector("_Velocity").y-.1f)<.0001,"scroll velocity");var importer=AssetImporter.GetAtPath(dir+"/mask.png") as TextureImporter;Check(!importer.sRGBTexture&&importer.wrapMode==TextureWrapMode.Clamp,"linear fixed mask");Check(!ShaderUtil.ShaderHasError(generated.shader),"shader imports without errors");
  var definition=JsonUtility.FromJson<FlowConfig>(File.ReadAllText(request));Check(definition.schemaVersion==2&&definition.layers.Length==2,"multi-area export schema imported");Check(generated.GetFloat("_LayerCount")==2,"both independent areas enabled on one material");Check(generated.GetTexture("_FlowTex")!=generated.GetTexture("_FlowTex1")&&generated.GetTexture("_Mask")!=generated.GetTexture("_Mask1"),"independent area texture and mask references");Check(Math.Abs(generated.GetVector("_Velocity1").x+.7f)<.0001f&&Math.Abs(generated.GetVector("_Velocity").y-.1f)<.0001f,"independent scroll speeds and directions mapped");Check(generated.GetColor("_Tint")==Color.white&&generated.GetColor("_Tint1")==Color.white,"neutral pattern tints exported");Check(generated.GetFloat("_Enabled2")==0,"unused shader areas disabled");
  var secondMask=AssetImporter.GetAtPath(dir+"/"+definition.layers[1].maskFile) as TextureImporter;Check(!secondMask.sRGBTexture&&secondMask.wrapMode==TextureWrapMode.Clamp,"second mask stays linear and stationary");
  string legacyDir=dir+"/legacy-check";Directory.CreateDirectory(legacyDir);File.Copy(dir+"/base.png",legacyDir+"/base.png",true);File.Copy(dir+"/flow.png",legacyDir+"/flow.png",true);File.Copy(dir+"/mask.png",legacyDir+"/mask.png",true);File.Copy(dir+"/cutout.png",legacyDir+"/cutout.png",true);File.WriteAllText(legacyDir+"/flow-request.json",JsonUtility.ToJson(new FlowConfig{schemaVersion=1}));AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);FlowImporter.Import(legacyDir+"/flow-request.json");var legacyMaterial=AssetDatabase.LoadAssetAtPath<Material>(legacyDir+"/Animated.mat");Check(legacyMaterial!=null&&legacyMaterial.GetFloat("_LayerCount")==1,"legacy single-area exports remain compatible");

  var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var avatar=new GameObject("Beginner test avatar");var go=new GameObject("Shoes");go.transform.SetParent(avatar.transform);shoes=go.AddComponent<MeshRenderer>();
  string originals="Assets/TextureFlowTests";Directory.CreateDirectory(originals);original=AssetDatabase.LoadAssetAtPath<Material>(originals+"/Original.mat");if(original==null){original=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(original,originals+"/Original.mat");}original.mainTexture=generated.GetTexture("_MainTex");other=AssetDatabase.LoadAssetAtPath<Material>(originals+"/Other.mat");if(other==null){other=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(other,originals+"/Other.mat");}shoes.sharedMaterials=new[]{original,other};EditorSceneManager.SaveScene(scene,originals+"/BridgeTest.unity");
  var snapshot=FlowBridge.Snapshot();Check(snapshot.targets.Any(t=>t.label.Contains("Beginner test avatar / Shoes")&&t.slot==0),"readable avatar part discovery");Check(snapshot.targets.Single(t=>t.instanceId==shoes.GetInstanceID()&&t.slot==0).texturePath==AssetDatabase.GetAssetPath(original.mainTexture),"base texture matching metadata");
  var command=Apply(materialPath);var reply=FlowBridge.Execute(command);Check(reply.success&&reply.applied&&shoes.sharedMaterials[0]==generated,"one-click apply assigns exact chosen slot");var repeated=FlowBridge.Execute(command);Check(repeated.success&&repeated.receiptPath==reply.receiptPath,"replayed apply request is idempotent");Check(shoes.sharedMaterials[1]==other,"other material slots remain unchanged");Check(File.Exists(reply.receiptPath),"restore receipt written");var receipt=JsonUtility.FromJson<FlowReceipt>(File.ReadAllText(reply.receiptPath));Check(AssetDatabase.LoadAssetAtPath<Material>(receipt.backupPath)!=null,"previous material backup created");Check(original.mainTexture==generated.GetTexture("_MainTex"),"original shared material unchanged");
  Undo.PerformUndo();Check(shoes.sharedMaterials[0]==original,"Unity Undo restores assignment");Undo.PerformRedo();Check(shoes.sharedMaterials[0]==generated,"Unity Redo restores effect");
  var restore=FlowBridge.Execute(new FlowCommand{requestId=Guid.NewGuid().ToString("N"),sessionId=FlowBridge.Session,action="restore",receiptPath=reply.receiptPath});Check(restore.success&&!restore.applied&&shoes.sharedMaterials[0]==original,"restore button recovers original reference");
  command=Apply(materialPath);shoes.sharedMaterials=new[]{other,other};Refuses(()=>FlowBridge.Execute(command),"stale material target refused");Check(shoes.sharedMaterials[0]==other,"stale target preserves newer material");shoes.sharedMaterials=new[]{original,other};
  command=Apply(materialPath);command.sessionId="previous-editor-session";Refuses(()=>FlowBridge.Execute(command),"old editor session refused");
  command=Apply(materialPath);command.expiresUtc=DateTime.UtcNow.AddMinutes(-1).ToString("O");Refuses(()=>FlowBridge.Execute(command),"expired request refused");
  command=Apply(materialPath);command.target.globalId="stale-global-id";Refuses(()=>FlowBridge.Execute(command),"stale renderer identity refused");
  command=Apply("Assets/OutsideExport.mat");Refuses(()=>FlowBridge.Execute(command),"non-export material path refused");
  command=Apply(materialPath);reply=FlowBridge.Execute(command);shoes.sharedMaterials=new[]{other,other};Refuses(()=>FlowBridge.Execute(new FlowCommand{sessionId=FlowBridge.Session,action="restore",receiptPath=reply.receiptPath}),"restore refuses to overwrite newer assignment");shoes.sharedMaterials=new[]{generated,other};FlowBridge.Execute(new FlowCommand{sessionId=FlowBridge.Session,action="restore",receiptPath=reply.receiptPath});
  command=Apply(materialPath);Directory.CreateDirectory(FlowBridge.Root+"/requests");File.WriteAllText(FlowBridge.Root+"/requests/"+command.requestId+".json",JsonUtility.ToJson(command));typeof(FlowBridge).GetField("next",BindingFlags.NonPublic|BindingFlags.Static).SetValue(null,0d);typeof(FlowBridge).GetMethod("Tick",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null);
  var queued=JsonUtility.FromJson<FlowReply>(File.ReadAllText(FlowBridge.Root+"/results/"+command.requestId+".json"));Check(queued.success&&shoes.sharedMaterials[0]==generated,"file protocol processes real apply request");FlowBridge.Execute(new FlowCommand{sessionId=FlowBridge.Session,action="restore",receiptPath=queued.receiptPath});
  command=Apply(materialPath);reply=FlowBridge.Execute(command);var crossSession=JsonUtility.FromJson<FlowReceipt>(File.ReadAllText(reply.receiptPath));crossSession.sessionId="prior-editor-session";File.WriteAllText(reply.receiptPath,JsonUtility.ToJson(crossSession));var crossRestore=FlowBridge.Execute(new FlowCommand{sessionId=FlowBridge.Session,action="restore",receiptPath=reply.receiptPath});Check(crossRestore.success&&shoes.sharedMaterials[0]==original,"saved-scene restore resolves stable renderer identity");
  FlowBridge.Publish();Check(File.Exists(FlowBridge.Root+"/connection.json"),"connector heartbeat published");AssetDatabase.SaveAssets();
  oldPlayOptions=EditorSettings.enterPlayModeOptionsEnabled;oldOptions=EditorSettings.enterPlayModeOptions;EditorSettings.enterPlayModeOptionsEnabled=true;EditorSettings.enterPlayModeOptions=EnterPlayModeOptions.DisableDomainReload|EnterPlayModeOptions.DisableSceneReload;EditorApplication.playModeStateChanged+=PlayChanged;EditorApplication.isPlaying=true;
 }catch(Exception ex){report+=ex+"\n";Debug.LogException(ex);Finish(1);}}
 static void PlayChanged(PlayModeStateChange state){try{if(state==PlayModeStateChange.EnteredPlayMode){Refuses(()=>FlowBridge.Execute(new FlowCommand{sessionId=FlowBridge.Session,action="apply"}),"application refused during Play mode");EditorApplication.isPlaying=false;}else if(state==PlayModeStateChange.EnteredEditMode){EditorApplication.playModeStateChanged-=PlayChanged;EditorSettings.enterPlayModeOptionsEnabled=oldPlayOptions;EditorSettings.enterPlayModeOptions=oldOptions;Finish(0);}}catch(Exception ex){report+=ex+"\n";Debug.LogException(ex);Finish(1);}}
}
